  {viewing&&canReviewSelected&&<section className="ow-campaign-owner-review"><h3>Owner xét duyệt</h3><p className="muted">Chiến dịch đang chờ Chủ tổ chức xét duyệt.</p><label>Nhận xét / lý do<textarea value={note} maxLength={2000} onChange={e=>setNote(e.target.value)}/></label><div className="actions">{[['APPROVE','Phê duyệt và công khai'],['REQUEST_CHANGES','Yêu cầu chỉnh sửa'],['REJECT','Từ chối']].map(([decision,label])=><button type="button" key={decision} disabled={busy||(decision!=='APPROVE'&&!note.trim())} onClick={()=>void action(async()=>{setSelected(await api<Campaign>(`/api/campaigns/${selected!.id}/review`,{method:'POST',body:JSON.stringify({version:selected!.version,decision,note})}));setMessage('Đã lưu kết quả xét duyệt.');})}>{label}</button>)}</div></section>}
